export const getStreamNotificationEventsUrl = (
  projectId: string,
  params?: StreamNotificationEventsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/notifications/events/prompt_lib/${projectId}?${stringifiedParams}`
    : `/notifications/events/prompt_lib/${projectId}`;
};

/**
 * Pushes each new notification of the caller as
 * `event: notifications_notify` with the Notification JSON as `data`
 * and its id as the SSE `id`. The first event is
 * `notifications_ready` with `{"cursor": N}` and `retry: 2000`; it is
 * also sent in place of a notification too large for the stream (then
 * read the list). Resume with `Last-Event-ID` or `?cursor=` (both and
 * different is a 400); without one the stream starts at the newest
 * notification. The list stays authoritative: after a reconnect gap,
 * sync the list (`changes_since`) rather than trusting the stream.
 * @summary New notifications for the caller, as Server-Sent Events
 */
export const streamNotificationEvents = async (
  projectId: string,
  params?: StreamNotificationEventsParams,
  options?: Parameters<typeof eliteaFetch>[1],
): Promise<streamNotificationEventsResponse> => {
  return eliteaFetch<streamNotificationEventsResponse>(
    getStreamNotificationEventsUrl(projectId, params),
    {
      ...options,
      method: "GET",
    },
  );
};

